    None 値は skip し dataclass default を尊重 (= CLI override 経路で None が
    入った場合の対応、 ``_args_to_overrides`` 由来)。
    """
    allowed = {
        "fitness_mode",
        "beta",
        "persistence_weight",
        "lucky_hard_penalty",
        "lucky_soft_penalty",
    }
    unknown_keys = set(raw.keys()) - allowed
