    kwargs: dict[str, Any] = {}
    if raw.get("fitness_mode") is not None:
        kwargs["fitness_mode"] = str(raw["fitness_mode"])
    for numeric_key in (
        "beta",
        "persistence_weight",
        "lucky_hard_penalty",
        "lucky_soft_penalty",
    ):
        if raw.get(numeric_key) is not None:
